/**
 * @name Code injection via eval/exec with untrusted input
 * @description Tracks remote/untrusted input into code execution sinks
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-numpy
 * @tags security external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CodeInjConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(CodeExecution ce).getCode()
  }
}

module CodeInjFlow = TaintTracking::Global<CodeInjConfig>;
import CodeInjFlow::PathGraph

from CodeInjFlow::PathNode source, CodeInjFlow::PathNode sink
where CodeInjFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection from $@.", source.getNode(), "user-controlled input"

/**
 * @name Path traversal via filesystem access with untrusted input
 * @description Tracks remote/untrusted input into filesystem path arguments
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-numpy
 * @tags security external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTravConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    sink = any(FileSystemAccess fsa).getAPathArgument()
  }
}

module PathTravFlow = TaintTracking::Global<PathTravConfig>;
import PathTravFlow::PathGraph

from PathTravFlow::PathNode source, PathTravFlow::PathNode sink
where PathTravFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user-controlled input"
